# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VARLIK FELSEFESİ (ONTOLOJİ): KONUSU VE TEMEL KAVRAMLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GERÇEK VE İDEAL (DÜŞÜNSEL) VARLIK</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#1d4ed8">• Gerçek (Reel) Varlık:</text>\n  <text x="44" y="106" font-size="10.6" fill="#1e3a8a">İnsan zihninden bağımsız olarak uzay ve zamanda</text>\n  <text x="44" y="122" font-size="10.6" fill="#1e3a8a">yer kaplayan, duyularla algılanan varlıklardır</text>\n  <text x="44" y="138" font-size="10.6" fill="#1e3a8a">(ağaç, taş, gezegen, masa, insan bedeni).</text>\n  <text x="34" y="160" font-size="11" font-weight="bold" fill="#1d4ed8">• İdeal (Düşünsel) Varlık:</text>\n  <text x="44" y="178" font-size="10.6" fill="#1e3a8a">Zihne bağımlı olan, zaman ve mekân dışı</text>\n  <text x="44" y="194" font-size="10.6" fill="#1e3a8a">soyut kavramlardır (sayılar, π sayısı, üçgen, Kafdağı).</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ONTOLOJİNİN TEMEL KAVRAMLARI</text>\n  <text x="370" y="88" font-size="10.8" fill="#14532d">• Töz (Cevher): Var olmak için başka bir şeye ihtiyaç</text>\n  <text x="380" y="103" font-size="10.4" fill="#14532d">duymayan, değişmeyen kalıcı temel dayanak.</text>\n  <text x="370" y="122" font-size="10.8" fill="#14532d">• İlinek (Araz): Tözün üzerinde gerçekleşen geçici nitelik.</text>\n  <text x="370" y="141" font-size="10.8" fill="#14532d">• Öz (Mahiyet): Bir varlığı o varlık yapan temel nitelik.</text>\n  <text x="370" y="160" font-size="10.8" fill="#14532d">• Oluş (Sayruret): Varlıktaki sürekli değişim ve dönüşüm.</text>\n  <text x="370" y="179" font-size="10.8" fill="#14532d">• Arkhe (İlk Neden): Evrenin kendisinden doğduğu ilk ana madde.</text>\n  <text x="370" y="198" font-size="10.8" fill="#14532d">• İdea ve Fenomen: Düşünsel asıl varlık ve görüngü.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bilimler varlığı parçalara ayırarak incelerken, ontoloji varlığı tümel (bütüncül) olarak sorgular.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">1. PROBLEM: VARLIĞIN VAR OLUP OLMADIĞI VE NİCELİĞİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">VARLIK VAR MIDIR? (NİHİLİZM VS. REALİZM)</text>\n  <text x="34" y="88" font-size="11" font-weight="bold" fill="#b91c1c">• Nihilizm (Hiççilik) — Gorgias ve Taoculuk:</text>\n  <text x="44" y="106" font-size="10.5" fill="#7f1d1d">Gerçekte hiçbir varlık yoktur; olsa da bilinemez;</text>\n  <text x="44" y="122" font-size="10.5" fill="#7f1d1d">bilinse de başkasına aktarılamaz (Gorgias).</text>\n  <text x="34" y="148" font-size="11" font-weight="bold" fill="#15803d">• Realizm (Gerçekçilik):</text>\n  <text x="44" y="166" font-size="10.5" fill="#14532d">İnsan bilincinden bağımsız bir varlık alanı</text>\n  <text x="44" y="182" font-size="10.5" fill="#14532d">gerçekten vardır ve varlığın mahiyeti tartışılabilir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">VARLIĞIN NİCELİĞİ (SAYISI NEDİR?)</text>\n  <text x="370" y="90" font-size="11" font-weight="bold" fill="#a16207">• Monizm (Tekçilik):</text>\n  <text x="380" y="108" font-size="10.5" fill="#713f12">Varlık tek bir ilkeden/tözden oluşur (Thales: Su,</text>\n  <text x="380" y="124" font-size="10.5" fill="#713f12">Hegel: Geist, Spinoza: Tanrı/Doğa).</text>\n  <text x="370" y="148" font-size="11" font-weight="bold" fill="#a16207">• Düalizm (İkicilik — Descartes):</text>\n  <text x="380" y="166" font-size="10.5" fill="#713f12">Varlık birbirine indirgenemeyen iki ayrı tözden</text>\n  <text x="380" y="182" font-size="10.5" fill="#713f12">oluşur: Ruh (düşünen töz) ve Madde (yer kaplayan töz).</text>\n  <text x="370" y="202" font-size="11" font-weight="bold" fill="#a16207">• Plüralizm (Çokçuluk — Empedokles): Su, hava, toprak, ateş.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Varlığın var olduğunu kabul eden реалиst filozoflar, varlığın niceliğini (sayısını) ve niteliğini (mahiyetini) sorgulamıştır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">2. PROBLEM: VARLIĞIN NE OLDUĞU (MAHİYETİ / NİTELİĞİ)</text>\n  <rect x="18" y="42" width="128" height="175" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="82" y="64" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e40af">1. Oluş Olarak</text>\n  <text x="82" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Herakleitos &amp;</text>\n  <text x="82" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Whitehead</text>\n  <text x="82" y="120" text-anchor="middle" font-size="9.8" fill="#1e3a8a">Durağan varlık</text>\n  <text x="82" y="135" text-anchor="middle" font-size="9.8" fill="#1e3a8a">yoktur; sürekli</text>\n  <text x="82" y="150" text-anchor="middle" font-size="9.8" fill="#1e3a8a">değişim ve akış</text>\n  <text x="82" y="165" text-anchor="middle" font-size="9.8" fill="#1e3a8a">(Logos) vardır.</text>\n  <rect x="154" y="42" width="128" height="175" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="218" y="64" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#166534">2. İdea Olarak</text>\n  <text x="218" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Platon, Aristo,</text>\n  <text x="218" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Farabi, Hegel</text>\n  <text x="218" y="120" text-anchor="middle" font-size="9.8" fill="#14532d">İdealizm: Asıl</text>\n  <text x="218" y="135" text-anchor="middle" font-size="9.8" fill="#14532d">varlık düşünsel,</text>\n  <text x="218" y="150" text-anchor="middle" font-size="9.8" fill="#14532d">tinsel ve ezeli</text>\n  <text x="218" y="165" text-anchor="middle" font-size="9.8" fill="#14532d">olan ideadır.</text>\n  <rect x="290" y="42" width="128" height="175" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="354" y="64" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#9a3412">3. Madde Olarak</text>\n  <text x="354" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#c2410c">Demokritos, Marx,</text>\n  <text x="354" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#c2410c">Hobbes, La Mettrie</text>\n  <text x="354" y="120" text-anchor="middle" font-size="9.8" fill="#7c2d12">Materyalizm: Varlık</text>\n  <text x="354" y="135" text-anchor="middle" font-size="9.8" fill="#7c2d12">maddedir; düşünce</text>\n  <text x="354" y="150" text-anchor="middle" font-size="9.8" fill="#7c2d12">maddenin ürünü ve</text>\n  <text x="354" y="165" text-anchor="middle" font-size="9.8" fill="#7c2d12">yansımasıdır.</text>\n  <rect x="426" y="42" width="128" height="175" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="1.8"/>\n  <text x="490" y="64" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#854d0e">4. İdea + Madde</text>\n  <text x="490" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">Descartes</text>\n  <text x="490" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#a16207">(Düalizm)</text>\n  <text x="490" y="120" text-anchor="middle" font-size="9.8" fill="#713f12">Yaratılan töz ikiye</text>\n  <text x="490" y="135" text-anchor="middle" font-size="9.8" fill="#713f12">ayrılır: Ruh (düşünce)</text>\n  <text x="490" y="150" text-anchor="middle" font-size="9.8" fill="#713f12">ve Madde (uzam /</text>\n  <text x="490" y="165" text-anchor="middle" font-size="9.8" fill="#713f12">yer kaplama).</text>\n  <rect x="562" y="42" width="120" height="175" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="622" y="64" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#6b21a8">5. Fenomen</text>\n  <text x="622" y="84" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">Edmund Husserl</text>\n  <text x="622" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">(Fenomenoloji)</text>\n  <text x="622" y="120" text-anchor="middle" font-size="9.8" fill="#581c87">Paranteze alma</text>\n  <text x="622" y="135" text-anchor="middle" font-size="9.8" fill="#581c87">(epokhe) ile</text>\n  <text x="622" y="150" text-anchor="middle" font-size="9.8" fill="#581c87">bilincin kavradığı</text>\n  <text x="622" y="165" text-anchor="middle" font-size="9.8" fill="#581c87">saf ÖZ\'e ulaşılır.</text>\n  <rect x="18" y="224" width="664" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.3" font-weight="bold" fill="#1e293b">Çağdaş ontolojide Nicolai Hartmann (Yeni Ontoloji) ve Jean-Paul Sartre (Varoluşçuluk) öne çıkmıştır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
